const ADMIN_EMAIL='agilizecertificadora@gmail.com';const $=s=>document.querySelector(s),money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((c||0)/100),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));let role='',data=null;const today=new Date().toISOString().slice(0,10);$('#month').value=today.slice(0,7);$('#entry-form').elements.operationDate.value=today;
async function api(url,opt={}){const res=await fetch(url,{credentials:'same-origin',...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});let body={};try{body=await res.json()}catch{}if(!res.ok)throw new Error(body.message||'Não foi possível concluir.');return body}
function message(id,text){$(id).textContent=text}
function showLogin(){ $('#login').hidden=false;$('#dashboard').hidden=true;$('#logout').hidden=true }
function showDashboard(session){role=session.role;$('#login').hidden=true;$('#dashboard').hidden=false;$('#logout').hidden=false;$('#user-email').textContent=session.email;document.querySelectorAll('.admin-only').forEach(x=>x.hidden=role!=='admin');load()}
async function session(){try{showDashboard(await api('/api/partner/session'))}catch{showLogin()}}
$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,b=form.querySelector('button');b.disabled=true;try{const email=form.elements.email.value.trim();const adminLogin=email.toLowerCase()===ADMIN_EMAIL;const out=await api(adminLogin?'/api/admin/auth/request-code':'/api/partner/auth/request-code',{method:'POST',body:JSON.stringify({email})});message('#auth-message',out.message);form.hidden=true;$('#code-form').hidden=false;$('#code-form').elements.code.focus()}catch(err){message('#auth-message',err.message)}finally{b.disabled=false}});
$('#code-form').addEventListener('submit',async e=>{e.preventDefault();try{const email=$('#login-form').elements.email.value.trim(),adminLogin=email.toLowerCase()===ADMIN_EMAIL;await api(adminLogin?'/api/admin/auth/verify-code':'/api/partner/auth/verify-code',{method:'POST',body:JSON.stringify({email,code:e.currentTarget.elements.code.value})});showDashboard({role:adminLogin?'admin':'partner',email})}catch(err){message('#auth-message',err.message)}});
$('#logout').addEventListener('click',async()=>{await api(role==='admin'?'/api/admin/auth/logout':'/api/partner/auth/logout',{method:'POST'});location.reload()});
async function load(){try{data=await api('/api/partner/dashboard?month='+encodeURIComponent($('#month').value));render()}catch(err){alert(err.message)}}
function render(){const s=data.summary;$('#welcome').textContent=data.settings?.partner_name?`Transparência e histórico de ${data.settings.partner_name}.`:'Configure o nome e o e-mail do sócio para liberar o acesso próprio.';$('#m-charged').textContent=money(s.charged);$('#m-cost').textContent=money(s.cost);$('#m-net').textContent=money(s.net);$('#m-partner').textContent=money(s.partner);$('#m-paid').textContent=money(s.paid);$('#m-pending').textContent=money(s.pending);$('#closure-badge').textContent=data.closure?`Mês fechado em ${new Date(data.closure.closed_at).toLocaleDateString('pt-BR')}`:'Mês em aberto';const select=$('#entry-form').elements.productId;select.replaceChildren(new Option('Escolha o produto',''));data.products.forEach(p=>select.add(new Option(`${p.title} · custo ${money(p.cost_cents)}`,p.product_id)));const tbody=$('#entries');tbody.replaceChildren();$('#empty').hidden=!!data.entries.length;data.entries.forEach(row=>{const tr=document.createElement('tr');const actions=role==='admin'?`<div class="row-actions"><button data-paid="${row.id}">${row.pix_status==='paid'?'Reabrir':'Marcar pago'}</button><label class="proof-label">${row.proof_name?'Trocar':'Anexar'}<input type="file" accept="application/pdf,image/*" data-proof="${row.id}"></label>${row.proof_name?`<button data-view="${row.id}">Ver</button>`:''}</div>`:(row.proof_name?`<button data-view="${row.id}">Ver comprovante</button>`:'—');tr.innerHTML=`<td>${row.operation_date.split('-').reverse().join('/')}</td><td><strong>${esc(row.customer_name)}</strong><small>${esc(row.product_title)}${row.order_protocol?' · '+esc(row.order_protocol):''}</small></td><td class="money">${money(row.charged_cents)}</td><td class="money">${money(row.cost_cents)}</td><td class="money">${money(row.net_cents)}</td><td class="money"><strong>${money(row.partner_share_cents)}</strong></td><td><span class="status ${row.pix_status}">${row.pix_status==='paid'?'Pago':'Pendente'}</span></td><td>${actions}</td>`;tbody.append(tr)});bindRows()}
function selected(){return data?.products.find(p=>p.product_id===$('#entry-form').elements.productId.value)}function calculate(){const f=$('#entry-form'),charged=Math.round(Number(f.elements.charged.value||0)*100),cost=Math.round(Number(f.elements.cost.value||0)*100),net=charged-cost;$('#calc-net').textContent=money(net);$('#calc-share').textContent=money(Math.round(net/2))}
$('#entry-form').elements.productId.addEventListener('change',()=>{const p=selected();if(p){$('#entry-form').elements.charged.value=p.sale_price_cents==null?'':(p.sale_price_cents/100).toFixed(2);$('#entry-form').elements.cost.value=(p.cost_cents/100).toFixed(2);calculate()}});$('#entry-form').elements.charged.addEventListener('input',calculate);$('#entry-form').elements.cost.addEventListener('input',calculate);
$('#entry-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await api('/api/partner/entries',{method:'POST',body:JSON.stringify({operationDate:f.elements.operationDate.value,productId:f.elements.productId.value,customerName:f.elements.customerName.value,orderProtocol:f.elements.orderProtocol.value,chargedCents:Math.round(Number(f.elements.charged.value)*100),costCents:Math.round(Number(f.elements.cost.value)*100),notes:f.elements.notes.value})});message('#entry-message','Lançamento registrado.');f.reset();f.elements.operationDate.value=today;await load()}catch(err){message('#entry-message',err.message)}finally{b.disabled=false}});
function bindRows(){document.querySelectorAll('[data-paid]').forEach(b=>b.onclick=async()=>{const row=data.entries.find(x=>x.id===b.dataset.paid);await api('/api/partner/entries/'+row.id,{method:'PATCH',body:JSON.stringify({pixStatus:row.pix_status==='paid'?'pending':'paid'})});load()});document.querySelectorAll('[data-proof]').forEach(i=>i.onchange=async()=>{const file=i.files[0];if(!file)return;if(file.size>1500000){alert('Escolha um arquivo de até 1,5 MB.');return}const row=data.entries.find(x=>x.id===i.dataset.proof),proofData=await new Promise(ok=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.readAsDataURL(file)});await api('/api/partner/entries/'+row.id,{method:'PATCH',body:JSON.stringify({pixStatus:row.pix_status,proofName:file.name,proofData})});load()});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{const out=await api('/api/partner/entries/'+b.dataset.view);const a=document.createElement('a');a.href=out.proof_data;a.download=out.proof_name||'comprovante';a.target='_blank';a.click()})}
$('#month').addEventListener('change',load);$('#refresh').addEventListener('click',load);$('#close-month').addEventListener('click',async()=>{if(confirm('Fechar este mês com os valores atuais?')){await api('/api/partner/closure',{method:'POST',body:JSON.stringify({month:$('#month').value})});load()}});$('#settings-button').addEventListener('click',()=>{const f=$('#settings-form');f.elements.partnerName.value=data.settings?.partner_name||'';f.elements.partnerEmail.value=data.settings?.partner_email||'';$('#settings').showModal()});$('#settings-close').addEventListener('click',()=>$('#settings').close());$('#settings-form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/partner/settings',{method:'PUT',body:JSON.stringify({partnerName:e.currentTarget.elements.partnerName.value,partnerEmail:e.currentTarget.elements.partnerEmail.value})});message('#settings-message','Acesso salvo.');setTimeout(()=>{$('#settings').close();load()},700)}catch(err){message('#settings-message',err.message)}});session();
